#!/usr/bin/env python3
# Simple TCP port scanner
# Only use on systems you own or have permission to test!

import socket
import sys
from concurrent.futures import ThreadPoolExecutor

def scan_port(host, port, timeout=1):
    """Returns True if port is open"""
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.settimeout(timeout)
        result = s.connect_ex((host, port))  # 0 = success (open)
        s.close()
        return result == 0
    except socket.error:
        return False

def scan_range(host, start_port, end_port, threads=100):
    """Scan a range of ports using thread pool"""
    open_ports = []

    with ThreadPoolExecutor(max_workers=threads) as executor:
        # Submit all port scans
        futures = {
            executor.submit(scan_port, host, port): port 
            for port in range(start_port, end_port + 1)
        }

        # Collect results
        for future, port in futures.items():
            if future.result():
                open_ports.append(port)

    return sorted(open_ports)

if __name__ == '__main__':
    target = sys.argv[1] if len(sys.argv) > 1 else '127.0.0.1'

    print(f'Scanning {target}...')
    open_ports = scan_range(target, 1, 1024)

    if open_ports:
        print(f'Open ports: {open_ports}')
        # Try to grab service banner
        for port in open_ports:
            try:
                s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                s.settimeout(2)
                s.connect((target, port))
                s.send(b'HEAD / HTTP/1.0\r\n\r\n')
                banner = s.recv(1024).decode('utf-8', errors='ignore').split('\n')[0]
                print(f'  Port {port}: {banner[:50]}')
                s.close()
            except:
                pass
    else:
        print('No open ports found in range 1-1024')

#!/usr/bin/env python3
# Query VirusTotal and Shodan APIs for threat intelligence
# Get free API keys from virustotal.com and shodan.io

import requests
import json
import os

# --- VIRUSTOTAL: Check if a file hash is malicious ---
def check_hash_virustotal(file_hash, api_key=None):
    api_key = api_key or os.environ.get('VT_API_KEY')

    url = f'https://www.virustotal.com/api/v3/files/{file_hash}'
    headers = {'x-apikey': api_key}

    response = requests.get(url, headers=headers)

    if response.status_code == 200:
        data = response.json()
        stats = data['data']['attributes']['last_analysis_stats']
        return {
            'malicious': stats.get('malicious', 0),
            'suspicious': stats.get('suspicious', 0),
            'harmless': stats.get('harmless', 0),
            'total': sum(stats.values())
        }
    elif response.status_code == 404:
        return {'error': 'Hash not found in VirusTotal'}
    else:
        return {'error': f'API error: {response.status_code}'}

# --- LOG ANALYSIS: Parse and filter log files ---
def analyze_auth_log(log_file='/var/log/auth.log'):
    """Find failed SSH login attempts"""
    failed_logins = {}

    with open(log_file, 'r', errors='ignore') as f:
        for line in f:
            if 'Failed password' in line:
                parts = line.split()
                try:
                    ip = parts[parts.index('from') + 1]
                    user = parts[parts.index('for') + 1]
                    key = f'{ip}:{user}'
                    failed_logins[key] = failed_logins.get(key, 0) + 1
                except (ValueError, IndexError):
                    continue

    # Sort by attempt count
    sorted_results = sorted(failed_logins.items(), key=lambda x: x[1], reverse=True)
    return sorted_results[:20]  # Top 20 attackers

# --- USAGE EXAMPLES ---
if __name__ == '__main__':
    # Check a hash
    # result = check_hash_virustotal('44d88612fea8a8f36de82e1278abb02f')  # EICAR test
    # print(json.dumps(result, indent=2))

    # Analyze auth logs (requires /var/log/auth.log access)
    try:
        attackers = analyze_auth_log()
        print('Top SSH brute force sources:')
        for attacker, count in attackers[:10]:
            print(f'  {attacker}: {count} attempts')
    except FileNotFoundError:
        print('Auth log not found. Run on a Linux system with /var/log/auth.log')
